 private TextView bubble(String role,String content){
  LinearLayout wrapper=col();boolean user=role.equals("user");wrapper.setGravity(user?Gravity.RIGHT:Gravity.LEFT);TextView v=label(user?content:FileReferences.display(content),17);v.setLineSpacing(dp(4),1);v.setTextIsSelectable(true);v.setPadding(dp(14),dp(12),dp(14),dp(12));v.setBackground(bg(user?0xfff2f2f2:Color.WHITE,0,20));
  if(!user){TextView who=text("蔚蓝 · "+name(service),12,0xff777777);who.setPadding(dp(12),dp(12),0,dp(4));wrapper.addView(who);}wrapper.addView(v,new LinearLayout.LayoutParams(user?-2:-1,-2));
  LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);chat.addView(wrapper,lp);if(!user)addFileCards(wrapper,content);return v;
 }
