 private void addFileCards(LinearLayout wrapper,String content){try{JSONArray refs=FileReferences.parse(content);for(int i=0;i<refs.length();i++){JSONObject ref=refs.getJSONObject(i);String name=ref.optString("name","引用文件");boolean image=name.toLowerCase(Locale.ROOT).matches(".*\\.(jpg|jpeg|png|gif|webp|bmp)$");LinearLayout card=col();card.setBackground(bg(0xfff6f6f6,0xffe8e8e8,12));card.setClipToOutline(true);card.setOnClickListener(v->openReference(ref,0));card.setOnLongClickListener(v->{fileMenu(ref);return true;});card.setContentDescription(name+"，点击打开，长按保存或分享");
 if(image){ImageView thumb=new ImageView(this);thumb.setScaleType(ImageView.ScaleType.FIT_CENTER);thumb.setBackgroundColor(0xfff3f3f3);thumb.setContentDescription(name+"缩略图");card.addView(thumb,new LinearLayout.LayoutParams(dp(174),dp(218)));TextView caption=text("正在加载缩略图…",11,0xff888888);caption.setPadding(dp(10),dp(7),dp(10),dp(7));caption.setSingleLine(true);caption.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(caption);loadThumbnail(ref,thumb,caption);}
 else{LinearLayout details=row();pad(details,12);String mime=ShareFiles.mime(name);TextView type=text(mime.equals("application/pdf")?"PDF":mime.contains("word")?"WORD":"FILE",12,Color.WHITE);type.setGravity(Gravity.CENTER);type.setTypeface(null,Typeface.BOLD);type.setBackground(bg(mime.equals("application/pdf")?0xffdf5454:0xff477bd5,0,8));details.addView(type,new LinearLayout.LayoutParams(dp(48),dp(56)));LinearLayout words=col();TextView filename=label(name,15);filename.setMaxLines(2);filename.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(filename);TextView hint=text("点击打开 · 长按分享",11,0xff999999);hint.setPadding(0,dp(6),0,0);words.addView(hint);LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,-2,1);wp.leftMargin=dp(12);details.addView(words,wp);card.addView(details);}
 LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(image?dp(174):dp(278),-2);lp.topMargin=dp(10);wrapper.addView(card,lp);}}catch(Exception ignored){}}
 private JSONObject referenceFile(JSONObject ref)throws Exception{return referenceFile(api,ref);}
 private JSONObject referenceFile(ApiClient client,JSONObject ref)throws Exception{JSONObject chunk=ApiClient.object(client.request("kb","/api/v1/chunks/by-id/"+URLEncoder.encode(ref.getString("chunk_id"),"UTF-8"),"GET",null,true));String id=chunk.getString("knowledge_id");JSONObject knowledge=ApiClient.object(client.request("kb","/api/v1/knowledge/"+URLEncoder.encode(id,"UTF-8"),"GET",null,true));JSONObject metadata=knowledge.optJSONObject("custom_metadata");if(metadata==null)metadata=knowledge.optJSONObject("metadata");String path=metadata==null?"":metadata.optString("nas_path","");String base="/api/v1/knowledge/"+URLEncoder.encode(id,"UTF-8");JSONObject file=new JSONObject().put("name",knowledge.optString("file_name",ref.optString("name"))).put("path",path);if(!path.isEmpty())file.put("name",path.replace("\\","/").substring(path.replace("\\","/").lastIndexOf("/")+1));if(path.isEmpty())file.put("_raw",base+"/preview").put("_download",base+"/download");return file;}
 private void loadThumbnail(JSONObject ref,ImageView view,TextView caption){final FrameLayout screen=frame;final String expected;try{expected=profile("kb");}catch(Exception e){caption.setText("点击查看 · 长按分享");return;}String key=expected+"|"+ref.optString("chunk_id");android.graphics.Bitmap cached=thumbnailCache.get(key);if(cached!=null){view.setImageBitmap(cached);caption.setText("点击放大 · 长按分享");return;}if(thumbnailRequests++>=20){caption.setText("点击查看 · 长按分享");return;}thumbnails.execute(()->{javax.net.ssl.HttpsURLConnection c=null;try{ApiClient client=new ApiClient(store);JSONObject file=referenceFile(client,ref);c=client.open("kb",rawPath(file),"GET",null,true);ApiClient.check(c);String type=c.getContentType();if(type==null||!type.toLowerCase(Locale.ROOT).startsWith("image/"))throw new IOException("非图片");byte[] data=ApiClient.bytes(c.getInputStream(),12*1024*1024);android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(data,0,data.length,options);if(options.outWidth<=0||options.outHeight<=0)throw new IOException("无效图片");options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>512)options.inSampleSize*=2;options.inJustDecodeBounds=false;android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(data,0,data.length,options);if(bitmap==null)throw new IOException("解码失败");if(!expected.equals(profile("kb")))return;thumbnailCache.put(key,bitmap);ui(()->{try{if(frame!=screen||!expected.equals(profile("kb")))return;view.setImageBitmap(bitmap);int height=Math.max(96,Math.min(240,Math.round(174f*bitmap.getHeight()/bitmap.getWidth())));view.setLayoutParams(new LinearLayout.LayoutParams(dp(174),dp(height)));caption.setText("点击放大 · 长按分享");}catch(Exception ignored){}});}catch(Exception e){ui(()->{if(frame==screen)caption.setText("点击查看原图 · 长按分享");});}finally{if(c!=null)c.disconnect();}});}
 private void openReference(JSONObject ref,int action){status.setText("正在读取原文件…");jobs.execute(()->{try{String expected=profile("kb");JSONObject file=referenceFile(ref);ui(()->{try{if(!expected.equals(profile("kb")))throw new Exception("账号已改变，请重新打开文件。");String name=file.optString("name").toLowerCase(Locale.ROOT);if(action==1)download(file);else if(action==2)externalFile(file,true);else if(name.matches(".*\\.(jpg|jpeg|png|gif|webp|bmp)$"))previewImage(file);else externalFile(file,false);}catch(Exception e){error(e);}});}catch(Exception e){ui(()->{status.setText("原文件读取失败");error(e);});}});}
 private void externalFile(JSONObject file,boolean share){status.setText("正在下载原文件…");jobs.execute(()->{javax.net.ssl.HttpsURLConnection c=null;File target=null;boolean complete=false;try{String expected=profile("kb"),name=ShareFiles.safeName(file.optString("name","文件"));String key=UUID.randomUUID().toString();target=ShareFiles.resolve(new File(getCacheDir(),"shared"),key,name);target.getParentFile().mkdirs();c=api.open("kb",file.optString("_download",rawPath(file)),"GET",null,true);ApiClient.check(c);String type=c.getContentType();if(type==null||type.toLowerCase(Locale.ROOT).contains("text/html")||type.toLowerCase(Locale.ROOT).contains("application/json"))throw new IOException("服务器没有返回原文件");long length=c.getContentLengthLong(),count=0;if(length>100L*1024*1024)throw new IOException("文件超过100MB，请在浏览器下载");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){count+=n;if(count>100L*1024*1024)throw new IOException("文件超过100MB");out.write(buffer,0,n);}}if(count==0||(length>=0&&count!=length))throw new IOException("文件传输不完整");if(!expected.equals(profile("kb")))throw new IOException("登录状态已改变");complete=true;Uri uri=new Uri.Builder().scheme("content").authority(getPackageName()+".sharedfiles").appendPath(key).appendPath(name).build();ui(()->{try{if(!expected.equals(profile("kb")))throw new IOException("登录状态已改变");Intent intent=new Intent(share?Intent.ACTION_SEND:Intent.ACTION_VIEW);if(share){intent.setType(ShareFiles.mime(name));intent.putExtra(Intent.EXTRA_STREAM,uri);}else intent.setDataAndType(uri,ShareFiles.mime(name));intent.setClipData(ClipData.newRawUri(name,uri));intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(intent,share?"选择微信或其他应用":"选择打开文件的应用"));status.setText("原文件已准备好");}catch(ActivityNotFoundException e){notice("手机没有可打开此文件的应用，请安装WPS或PDF阅读器，也可以先保存文件。");}catch(Exception e){error(e);}});}catch(Exception e){ui(()->error(e));}finally{if(c!=null)c.disconnect();if(!complete&&target!=null)target.delete();}});}
 private void scroll(){if(conversation!=null)conversation.post(()->conversation.fullScroll(View.FOCUS_DOWN));}
